// Hair root placement (paper Section 3.3) and the progressive blue-noise sample sets
// generated by sample elimination (Yuksel 2015).
#pragma once

#include <cstdint>
#include <string>
#include <vector>

#include "silkcrowd/math.h"

namespace silk {

// A precomputed 2D sample set. The set is *progressive*: any number of samples taken
// from the beginning forms a blue noise distribution, so bundles can render any strand
// count with a natural root distribution (Section 3.3).
struct SampleSet2D {
    std::vector<Vec2> samples;  // progressive order
    bool triangleDomain = false;

    size_t size() const { return samples.size(); }
    // Samples are indexed by the local strand index; if a bundle needs more strands than
    // the set holds, it wraps (a second set can be used for extra variety).
    const Vec2& at(size_t i) const { return samples[i % samples.size()]; }
};

struct SampleEliminationParams {
    size_t targetCount = 1024;   // how many progressive samples are kept
    size_t oversample = 4;       // initial candidates = targetCount * oversample
    float weightExponent = 8.0f; // (1 - d/r_max)^8, as in Yuksel 2015
    uint32_t seed = 12345u;
    bool triangleDomain = false;
};

// Runs sample elimination, recording the removal order so that the returned array is a
// progressive blue noise sequence of `targetCount` samples.
SampleSet2D generateBlueNoiseSamples(const SampleEliminationParams& p);

// Blue noise quality metrics (used by the validation suite / README chart).
struct BlueNoiseMetrics {
    double meanNearestNeighbor = 0.0;   // in the unit square
    double expectedWhiteNoise = 0.0;    // 0.5/sqrt(N) for white noise
    double varianceNN = 0.0;
    double minNN = 0.0, maxNN = 0.0;
    double radialDistributionScore = 0.0;  // 0 = terrible, 1 = ideal
    std::string toString() const;
};
BlueNoiseMetrics measureBlueNoise(const std::vector<Vec2>& pts);

// ---------------------------------------------------------------------------
//  Section 3.3: mapping a 2D sample onto the root slice of a bundle.
// ---------------------------------------------------------------------------
enum class TriangleMapping {
    // The mapping that makes |xi_Delta| reproduce barycentric interpolation with
    // coordinates (xi_s, xi_t, 1 - xi_s - xi_t) exactly:
    //     xi_Delta_s = xi_s / (1 - xi_t) ,  xi_Delta_t = xi_t
    // (see docs/PAPER_MAPPING.md for why this is used instead of the literal
    //  expression printed in the paper.)
    Barycentric,
    // The expression printed in Section 3.3: xi_Delta_s = xi_s (1 - xi_t).
    // Kept for the bias comparison in the validation suite.
    PaperLiteral,
};

// For a quad bundle the 2D sample maps directly into the 2x2 block.
inline Vec2 rootPlacementQuad(Vec2 xi) { return xi; }

// For a triangle bundle: the sample set lives in the triangular half xi_s + xi_t < 1 and
// is mapped onto the full bilinear block.
Vec2 rootPlacementTriangle(Vec2 xi, TriangleMapping mapping = TriangleMapping::Barycentric);

// Barycentric coordinates recovered by a bilinear lookup at the mapped position for a
// triangle whose duplicated vertex sits at block coordinates (0,1) and (1,1).
void triangleBarycentricsFromBlock(Vec2 ab, float* b0, float* b1, float* b2);

}  // namespace silk
